package com.quantaedge.api;
import java.math.BigDecimal;import java.sql.Date;import java.time.LocalDate;import java.time.OffsetDateTime;import java.time.format.DateTimeParseException;import java.util.List;import java.util.Map;
import org.springframework.dao.DuplicateKeyException;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/hr")
public class HrAttendanceLeaveController {
 private static final List<String> STATUSES=List.of("PRESENT","ABSENT","HALF_DAY","REMOTE","ON_LEAVE","HOLIDAY");private final JdbcTemplate jdbc;private final AuthorizationService auth;private final StaffAuditService audit;
 public HrAttendanceLeaveController(JdbcTemplate j,AuthorizationService a,StaffAuditService s){jdbc=j;auth=a;audit=s;}
 @GetMapping("/attendance") public Map<String,Object> attendance(@RequestAttribute(value="authContext",required=false) AuthContext c,@RequestParam(required=false) String from,@RequestParam(required=false) String to,@RequestParam(required=false) Long employeeId,@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="100") int limit){
 require(c,"HR_ATTENDANCE_VIEW");LocalDate end=to==null||to.isBlank()?LocalDate.now():date(to,"End date"),start=from==null||from.isBlank()?end.minusDays(30):date(from,"Start date");range(start,end,93);int lim=Math.max(1,Math.min(limit,200)),off=Math.max(0,Math.min(offset,1000000));
 List<Map<String,Object>> items=jdbc.queryForList("""
 select a.id,a.employee_id,e.employee_number,e.display_name,a.work_date,a.attendance_status,a.check_in_at,a.check_out_at,case when a.check_in_at is not null and a.check_out_at is not null then floor(extract(epoch from (a.check_out_at-a.check_in_at))/60)::int else null end minutes_worked,a.notes,a.recorded_by_staff_id,a.updated_by_staff_id,a.created_at,a.updated_at from hr_attendance_record a join hr_employee e on e.id=a.employee_id where a.work_date between ? and ? and (cast(? as bigint) is null or a.employee_id=?) order by a.work_date desc,e.display_name limit ? offset ?
 """,Date.valueOf(start),Date.valueOf(end),employeeId,employeeId,lim,off);
 Long total=jdbc.queryForObject("select count(*) from hr_attendance_record where work_date between ? and ? and (cast(? as bigint) is null or employee_id=?)",Long.class,Date.valueOf(start),Date.valueOf(end),employeeId,employeeId);return Map.of("items",items,"total",total==null?0L:total,"from",start.toString(),"to",end.toString(),"limit",lim,"offset",off);}
 @GetMapping("/attendance/summary") public Map<String,Object> summary(@RequestAttribute(value="authContext",required=false) AuthContext c,@RequestParam(required=false) String date){require(c,"HR_ATTENDANCE_VIEW");LocalDate d=date==null||date.isBlank()?LocalDate.now():date(date,"Date");Map<String,Object> r=jdbc.queryForMap("""
 select count(*) active_employees,count(a.id) marked,count(*) filter(where a.attendance_status='PRESENT') present,count(*) filter(where a.attendance_status='REMOTE') remote,count(*) filter(where a.attendance_status='HALF_DAY') half_day,count(*) filter(where a.attendance_status='ABSENT') absent,count(*) filter(where a.attendance_status='ON_LEAVE') on_leave,count(*) filter(where a.attendance_status='HOLIDAY') holiday from hr_employee e left join hr_attendance_record a on a.employee_id=e.id and a.work_date=? where e.employment_status='ACTIVE'
 """,Date.valueOf(d));r.put("date",d.toString());return r;}
 @PutMapping("/attendance/{employeeId}/{workDate}") @Transactional public Map<String,Object> saveAttendance(@PathVariable long employeeId,@PathVariable String workDate,@RequestBody Map<String,Object> b,@RequestAttribute(value="authContext",required=false) AuthContext c){
 require(c,"HR_ATTENDANCE_MANAGE");LocalDate d=date(workDate,"Work date");String st=required(b.get("status"),16,"Attendance status").toUpperCase();if(!STATUSES.contains(st))throw bad("Choose a supported attendance status.");Map<String,Object> emp=activeEmployee(employeeId);OffsetDateTime in=timestamp(b.get("checkInAt"),"Check-in time"),out=timestamp(b.get("checkOutAt"),"Check-out time");if(out!=null&&in==null)throw bad("A check-out time requires a check-in time.");if(in!=null&&out!=null&&!out.isAfter(in))throw bad("Check-out must be later than check-in.");if(List.of("ABSENT","ON_LEAVE","HOLIDAY").contains(st)&&(in!=null||out!=null))throw bad("Absent, on-leave and holiday records cannot have check-in/out times.");
 if("ON_LEAVE".equals(st)){Boolean ok=jdbc.queryForObject("select exists(select 1 from hr_leave_request where employee_id=? and request_status='APPROVED' and start_date<=? and end_date>=?)",Boolean.class,employeeId,Date.valueOf(d),Date.valueOf(d));if(!Boolean.TRUE.equals(ok))throw bad("Mark ON_LEAVE only when an approved leave request covers this date.");}
 Map<String,Object> priorRows=jdbc.queryForList("select id,attendance_status,check_in_at,check_out_at,notes from hr_attendance_record where employee_id=? and work_date=?",employeeId,Date.valueOf(d)).stream().findFirst().orElse(null);
 String note=optional(b.get("notes"),500);
 if(priorRows!=null){
   String reason=required(b.get("correctionReason"),1000,"Correction reason");
   jdbc.update("insert into hr_attendance_correction_history(attendance_record_id,employee_id,work_date,previous_status,previous_check_in_at,previous_check_out_at,previous_notes,corrected_status,corrected_check_in_at,corrected_check_out_at,corrected_notes,correction_reason,changed_by_staff_id) values (?,?,?,?,?,?,?,?,?,?,?,?,?)",
     priorRows.get("id"),employeeId,Date.valueOf(d),priorRows.get("attendance_status"),priorRows.get("check_in_at"),priorRows.get("check_out_at"),priorRows.get("notes"),st,in,out,note,reason,c.staffId());
 }
 Long id=jdbc.queryForObject("insert into hr_attendance_record(employee_id,work_date,attendance_status,check_in_at,check_out_at,notes,recorded_by_staff_id,updated_by_staff_id) values (?,?,?,?,?,?,?,?) on conflict(employee_id,work_date) do update set attendance_status=excluded.attendance_status,check_in_at=excluded.check_in_at,check_out_at=excluded.check_out_at,notes=excluded.notes,updated_by_staff_id=excluded.updated_by_staff_id,updated_at=now() returning id",Long.class,employeeId,Date.valueOf(d),st,in,out,note,c.staffId(),c.staffId());
 Map<String,Object> row=jdbc.queryForMap("select a.id,a.employee_id,e.employee_number,e.display_name,a.work_date,a.attendance_status,a.check_in_at,a.check_out_at,a.notes,a.recorded_by_staff_id,a.updated_by_staff_id,a.created_at,a.updated_at from hr_attendance_record a join hr_employee e on e.id=a.employee_id where a.id=?",id);audit.recordAction(c,"/api/v1/hr/attendance/"+employeeId+"/"+d,"Recorded attendance "+st+" for "+emp.get("employee_number")+" on "+d);return row;}
 @GetMapping("/attendance/{employeeId}/{workDate}/corrections") public Map<String,Object> attendanceCorrections(@PathVariable long employeeId,@PathVariable String workDate,@RequestAttribute(value="authContext",required=false) AuthContext c){
 require(c,"HR_ATTENDANCE_VIEW");LocalDate d=date(workDate,"Work date");activeEmployee(employeeId);
 List<Map<String,Object>> items=jdbc.queryForList("select h.id,h.attendance_record_id,h.employee_id,h.work_date,h.previous_status,h.previous_check_in_at,h.previous_check_out_at,h.previous_notes,h.corrected_status,h.corrected_check_in_at,h.corrected_check_out_at,h.corrected_notes,h.correction_reason,h.changed_by_staff_id,h.changed_at from hr_attendance_correction_history h where h.employee_id=? and h.work_date=? order by h.changed_at desc,h.id desc",employeeId,Date.valueOf(d));
 return Map.of("items",items,"total",items.size(),"employeeId",employeeId,"workDate",d.toString());
 }
 @GetMapping("/leave/types") public List<Map<String,Object>> types(@RequestAttribute(value="authContext",required=false) AuthContext c){require(c,"HR_LEAVE_VIEW");return jdbc.queryForList("select code,display_name,paid from hr_leave_type where active=true order by display_name");}
 @GetMapping("/leave/requests") public Map<String,Object> leaves(@RequestAttribute(value="authContext",required=false) AuthContext c,@RequestParam(defaultValue="ALL") String status,@RequestParam(required=false) Long employeeId,@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="100") int limit){
 require(c,"HR_LEAVE_VIEW");String st=status==null?"ALL":status.trim().toUpperCase();if(!List.of("ALL","PENDING","APPROVED","REJECTED","CANCELLED").contains(st))throw bad("Choose a supported leave-request status.");int lim=Math.max(1,Math.min(limit,200)),off=Math.max(0,Math.min(offset,1000000));
 List<Map<String,Object>> items=jdbc.queryForList("""
 select r.id,r.public_id,r.employee_id,e.employee_number,e.display_name,r.leave_type_code,t.display_name leave_type,t.paid,r.start_date,r.end_date,r.requested_days,r.reason,r.request_status,r.review_note,r.reviewed_by_staff_id,r.reviewed_at,r.created_by_staff_id,r.created_at,r.updated_at from hr_leave_request r join hr_employee e on e.id=r.employee_id join hr_leave_type t on t.code=r.leave_type_code where (?='ALL' or r.request_status=?) and (cast(? as bigint) is null or r.employee_id=?) order by case r.request_status when 'PENDING' then 0 else 1 end,r.created_at desc limit ? offset ?
 """,st,st,employeeId,employeeId,lim,off);Long total=jdbc.queryForObject("select count(*) from hr_leave_request where (?='ALL' or request_status=?) and (cast(? as bigint) is null or employee_id=?)",Long.class,st,st,employeeId,employeeId);return Map.of("items",items,"total",total==null?0L:total,"limit",lim,"offset",off);}
 @PostMapping("/leave/requests") @Transactional public Map<String,Object> createLeave(@RequestBody Map<String,Object> b,@RequestAttribute(value="authContext",required=false) AuthContext c){
 require(c,"HR_LEAVE_MANAGE");long eid=positive(b.get("employeeId"),"Employee");Map<String,Object> emp=activeEmployee(eid);String type=required(b.get("leaveTypeCode"),32,"Leave type").toUpperCase();Boolean valid=jdbc.queryForObject("select exists(select 1 from hr_leave_type where code=? and active=true)",Boolean.class,type);if(!Boolean.TRUE.equals(valid))throw bad("Choose an active leave type.");
 LocalDate start=date(required(b.get("startDate"),10,"Start date"),"Start date"),end=date(required(b.get("endDate"),10,"End date"),"End date");if(end.isBefore(start))throw bad("Leave end date cannot be before its start date.");if(java.time.temporal.ChronoUnit.DAYS.between(start,end)+1>366)throw bad("A leave request cannot exceed 366 calendar days.");
 Boolean overlap=jdbc.queryForObject("select exists(select 1 from hr_leave_request where employee_id=? and request_status in ('PENDING','APPROVED') and start_date<=? and end_date>=?)",Boolean.class,eid,Date.valueOf(end),Date.valueOf(start));if(Boolean.TRUE.equals(overlap))throw new ResponseStatusException(HttpStatus.CONFLICT,"This employee already has a pending or approved leave request overlapping those dates.");
 long orgId=((Number)emp.get("organization_id")).longValue();Integer workingDays=jdbc.queryForObject("select working_days_per_week from hr_organization where id=?",Integer.class,orgId);if(workingDays==null)workingDays=5;BigDecimal days=jdbc.queryForObject("select count(*)::numeric from generate_series(?::date,?::date,interval '1 day') as days(day) where extract(isodow from day)<=? and not exists(select 1 from hr_holiday_calendar h where h.organization_id=? and h.holiday_date=day and h.active=true)",BigDecimal.class,Date.valueOf(start),Date.valueOf(end),workingDays,orgId);if(days==null||days.signum()<=0)throw bad("The requested range contains no working days after applying the organisation schedule and official holidays.");
 Long id;try{id=jdbc.queryForObject("insert into hr_leave_request(employee_id,leave_type_code,start_date,end_date,requested_days,reason,created_by_staff_id) values (?,?,?,?,?,?,?) returning id",Long.class,eid,type,Date.valueOf(start),Date.valueOf(end),days,required(b.get("reason"),1000,"Reason"),c.staffId());}catch(DuplicateKeyException ex){throw new ResponseStatusException(HttpStatus.CONFLICT,"The leave request conflicts with an existing record.");}
 Map<String,Object> row=leaveById(id);audit.recordAction(c,"/api/v1/hr/leave/requests/"+id,"Created leave request for "+emp.get("employee_number"));return row;}
 @PatchMapping("/leave/requests/{id}/decision") @Transactional public Map<String,Object> decide(@PathVariable long id,@RequestBody Map<String,Object> b,@RequestAttribute(value="authContext",required=false) AuthContext c){
 require(c,"HR_LEAVE_MANAGE");Map<String,Object> before=leaveById(id);if(!"PENDING".equals(before.get("request_status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending leave requests can be reviewed.");String decision=required(b.get("status"),16,"Decision").toUpperCase();if(!List.of("APPROVED","REJECTED").contains(decision))throw bad("A leave decision must be APPROVED or REJECTED.");
 if(c.staffId()!=null){Boolean self=jdbc.queryForObject("select exists(select 1 from hr_employee where id=? and linked_staff_account_id=?)",Boolean.class,before.get("employee_id"),c.staffId());if(Boolean.TRUE.equals(self))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Employees cannot approve their own leave request.");}
 int changed=jdbc.update("update hr_leave_request set request_status=?,review_note=?,reviewed_by_staff_id=?,reviewed_at=now(),updated_at=now() where id=? and request_status='PENDING'",decision,optional(b.get("reviewNote"),1000),c.staffId(),id);if(changed!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"This leave request was already reviewed.");Map<String,Object> after=leaveById(id);audit.recordAction(c,"/api/v1/hr/leave/requests/"+id+"/decision",decision+" leave request "+id);return after;}
 private Map<String,Object> activeEmployee(long id){List<Map<String,Object>> r=jdbc.queryForList("select id,organization_id,employee_number,display_name,employment_status from hr_employee where id=? and employment_status not in ('SEPARATED','INACTIVE','DRAFT')",id);if(r.isEmpty())throw bad("Choose an active employee.");return r.getFirst();}
 private Map<String,Object> leaveById(long id){List<Map<String,Object>> r=jdbc.queryForList("select r.id,r.public_id,r.employee_id,e.employee_number,e.display_name,r.leave_type_code,t.display_name leave_type,t.paid,r.start_date,r.end_date,r.requested_days,r.reason,r.request_status,r.review_note,r.reviewed_by_staff_id,r.reviewed_at,r.created_by_staff_id,r.created_at,r.updated_at from hr_leave_request r join hr_employee e on e.id=r.employee_id join hr_leave_type t on t.code=r.leave_type_code where r.id=?",id);if(r.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Leave request not found.");return r.getFirst();}
 private void range(LocalDate a,LocalDate b,int max){if(b.isBefore(a))throw bad("End date cannot be before start date.");if(java.time.temporal.ChronoUnit.DAYS.between(a,b)>max)throw bad("Date range cannot exceed "+(max+1)+" days.");}
 private LocalDate date(String s,String label){try{return LocalDate.parse(s);}catch(RuntimeException e){throw bad(label+" must use YYYY-MM-DD format.");}}
 private OffsetDateTime timestamp(Object v,String label){if(v==null||String.valueOf(v).isBlank())return null;try{return OffsetDateTime.parse(String.valueOf(v));}catch(DateTimeParseException e){throw bad(label+" must be an ISO-8601 timestamp with timezone.");}}
 private long positive(Object v,String label){try{long n=Long.parseLong(String.valueOf(v));if(n>0)return n;}catch(RuntimeException ignored){}throw bad(label+" ID must be a positive integer.");}
 private String required(Object v,int max,String label){if(!(v instanceof String s)||s.trim().isEmpty()||s.trim().length()>max)throw bad(label+" is required and must be no longer than "+max+" characters.");return s.trim();}
 private String optional(Object v,int max){if(v==null)return null;String s=String.valueOf(v).trim();if(s.isEmpty())return null;if(s.length()>max)throw bad("A text field exceeds its maximum length of "+max+" characters.");return s;}
 private void require(AuthContext c,String p){auth.requirePermission(c,p);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
}